phase('Build')
log('Relaunching after the usage-limit stop: AI package → worker integration; web foundation → Video Studio UI; then dev-ops/docs')

const backend = (async () => {
  const ai = await agent(AI + AI_EXTRA + STATE, { label: 'ai-package', phase: 'Build', schema: REPORT_SCHEMA })
  const integrator = await agent(`${INTEGRATOR}

REPORT FROM THE AI PACKAGE AGENT:
${JSON.stringify(ai, null, 1)}`, { label: 'worker-integrator', phase: 'Build', schema: REPORT_SCHEMA })
  const devops = await agent(DEVOPS_DOCS + STATE + `

The worker integrator has finished; its report (use it for accurate README/testing docs):
${JSON.stringify(integrator, null, 1).slice(0, 20000)}`, { label: 'devops-docs', phase: 'Build', schema: REPORT_SCHEMA, effort: 'high' })
  return { ai, integrator, devops }
})()

const frontend = (async () => {
  const web = await agent(WEB_FOUNDATION + STATE, { label: 'web-foundation', phase: 'Build', schema: REPORT_SCHEMA, effort: 'high' })
  const studio = await agent(`${STUDIO_UI}

REPORT FROM THE WEB FOUNDATION AGENT:
${JSON.stringify(web, null, 1)}`, { label: 'studio-ui', phase: 'Build', schema: REPORT_SCHEMA, effort: 'high' })
  return { web, studio }
})()

const [b, f] = await Promise.all([backend, frontend])

phase('Verify')
const e2e = await agent(`${E2E}

REPORTS FROM THE BUILD AGENTS:
${JSON.stringify({ ai: b.ai, integrator: b.integrator, web: f.web, studio: f.studio }, null, 1).slice(0, 60000)}`, { label: 'e2e-browser', phase: 'Verify', schema: REPORT_SCHEMA, effort: 'high' })

return { ai: b.ai, integrator: b.integrator, devops: b.devops, web: f.web, studio: f.studio, e2e }
